import {spawn} from 'node:child_process';
import {readFile,writeFile,rm,mkdir,stat} from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {Context} from './lib/core.mjs';
import {nativeUi} from './lib/process-native.mjs';
const observations=[],children=[];let helperCounter=0;
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function wait(fn,label,ms=15000){const began=Date.now();for(;;){try{const value=await fn();if(value)return value;}catch{}if(Date.now()-began>ms)throw new Error(label);await pause(30);}}
function launch(program,args,env){const child=spawn(program,args,{shell:false,env,stdio:['ignore','pipe','pipe']});const chunks=[];child.stdout.on('data',v=>chunks.push(v));child.stderr.on('data',v=>chunks.push(v));child.closed=new Promise(r=>child.once('close',(code,signal)=>{child.result={code,signal,output:Buffer.concat(chunks).toString()};r();}));children.push(child);return child;}
const env={...process.env,DISPLAY:':91',NO_AT_BRIDGE:'0',XDG_RUNTIME_DIR:'/tmp/owned-xdg'};
process.env.DISPLAY=env.DISPLAY;process.env.NO_AT_BRIDGE='0';process.env.XDG_RUNTIME_DIR=env.XDG_RUNTIME_DIR;
await mkdir(env.XDG_RUNTIME_DIR,{mode:0o700});
let gtk,xvfb;
try{
 xvfb=launch('Xvfb',[':91','-screen','0','800x600x24','-nolisten','tcp','-ac'],env);await wait(()=>stat('/tmp/.X11-unix/X91'),'Xvfb socket did not become ready');
 gtk=launch('/usr/bin/python3',['-I','-B','/proof/owned-gtk.py'],env);const selected=await wait(async()=>JSON.parse(await readFile('/artifacts/selected.json')),'Owned GTK window did not become ready');await pause(500);
 const ctx=new Context();ctx.handlers={observe_native_ui:(args,ctx)=>nativeUi(args,ctx,false),capture_native_ui_scenario:(args,ctx)=>nativeUi(args,ctx,true)};
 const original=ctx.run.bind(ctx),helperPids=[];let cancellationMarker=null;
 ctx.run=async(argv,options)=>{const file='/artifacts/helper-'+(++helperCounter)+'.json';let selectedArgv=[...argv];if(cancellationMarker){assert(selectedArgv.at(-1).includes('initial=snapshot();last=initial;steps=[]'));selectedArgv[selectedArgv.length-1]=selectedArgv.at(-1).replace('initial=snapshot();last=initial;steps=[]','initial=snapshot();last=initial;steps=[]\nwith open('+JSON.stringify(cancellationMarker)+',"w") as owned:owned.write(str(os.getpid()))');}
  try{return await original(['/usr/bin/python3','-I','-B','/proof/helper-launcher.py',...selectedArgv],{...options,env:{...options.env,OWNED_HELPER_PID_FILE:file}});}catch(error){await writeFile('/artifacts/helper-'+helperCounter+'-failure.json',JSON.stringify({message:error.message,stdout:error.stdout,stderr:error.stderr},null,2));throw error;}finally{const row=JSON.parse(await readFile(file));helperPids.push(row.pid);await assert.rejects(stat('/proc/'+row.pid),e=>e.code==='ENOENT');}};
 const first=await ctx.call('observe_native_ui',{...selected,screenshot:true,max_nodes:100});await writeFile('/artifacts/OBSERVE.json',JSON.stringify(first,null,2));const initial=first.normalized_result.initial;
 assert.equal(initial.window.pid,selected.pid);assert.equal(initial.window.window_id,selected.window_id);assert.equal(initial.truncated,false);assert.equal(JSON.stringify(first).includes('OWNED_PASSWORD_NEVER_RETAIN'),false);
 const image=initial.screenshot;assert(image,'Actual selected-window screenshot must be present for this fixture');const png=Buffer.from(image.base64,'base64');assert.equal(createHash('sha256').update(png).digest('hex'),image.sha256);assert.equal(png.subarray(1,4).toString(),'PNG');assert.equal(image.width,320);assert.equal(image.height,240);
 const button=initial.nodes.find(n=>n.title==='Owned click'),entry=initial.nodes.find(n=>n.title==='Owned entry'),scroll=initial.nodes.find(n=>n.title==='Owned scroll');assert(button?.actions.includes('click'));assert(entry?.actions.includes('key-entry'));assert(scroll?.actions.includes('scroll'));
 const replay=await ctx.call('capture_native_ui_scenario',{...selected,screenshot:true,max_nodes:100,steps:[{kind:'key-entry',path:entry.path,text:'Owned edited value'},{kind:'click',path:button.path},{kind:'scroll',path:scroll.path,direction:'increment'}]});await writeFile('/artifacts/REPLAY.json',JSON.stringify(replay,null,2));assert(replay.normalized_result.steps.every(s=>s.outcome==='completed'),JSON.stringify(replay.normalized_result.steps));assert.deepEqual(JSON.parse(await readFile('/artifacts/effects.json')),{clicks:1,text:'Owned edited value',scroll:10});assert.notEqual(replay.normalized_result.steps.at(-1).after.screenshot.sha256,image.sha256);observations.push({case:'actual-selected-window-and-actions',success:true,pid:selected.pid,window_id:selected.window_id,screenshot_sha256:image.sha256,nodes:initial.nodes.length,independent_effects:true});
 const limited=(await ctx.call('observe_native_ui',{...selected,screenshot:false,max_nodes:2})).normalized_result.initial;assert.equal(limited.nodes.length,2);assert.equal(limited.truncated,true);observations.push({case:'bounded-node-retention',success:true,retained_nodes:2,truncation_reported:true});const hidden=(await ctx.call('observe_native_ui',{...selected,screenshot:false,accessibility:false})).normalized_result.initial;assert.deepEqual(hidden.nodes,[]);assert.equal(hidden.screenshot,null);observations.push({case:'requested-no-accessibility-or-pixels',success:true});
 let ledger=ctx.ledger.size;await assert.rejects(ctx.call('observe_native_ui',{...selected,pid:selected.pid+1000000,screenshot:false}),/could not be matched/);assert.equal(ctx.ledger.size,ledger);assert.deepEqual(JSON.parse(await readFile('/artifacts/effects.json')),{clicks:1,text:'Owned edited value',scroll:10});observations.push({case:'wrong-pid',success:true,no_publication:true,effects_preserved:true});
 const spoof=launch('/usr/bin/python3',['-I','-B','/proof/owned-spoof.py',String(selected.pid)],env),forged=await wait(async()=>JSON.parse(await readFile('/artifacts/spoofed-window.json')),'Owned spoofed X11 window did not become ready');assert.equal(forged.claimed_pid,selected.pid);assert.notEqual(forged.pid,selected.pid);await assert.rejects(ctx.call('observe_native_ui',{...selected,window_id:forged.window_id,screenshot:false}),/could not be matched/);assert.equal(ctx.ledger.size,ledger);observations.push({case:'forged-client-pid-property',success:true,claimed_pid:forged.claimed_pid,actual_owner_pid:forged.pid,no_publication:true});spoof.kill('SIGTERM');await spoof.closed;
 await assert.rejects(ctx.call('observe_native_ui',{...selected,window_id:99999999,screenshot:false}),/could not be matched/);assert.equal(ctx.ledger.size,ledger);observations.push({case:'wrong-native-window-id',success:true,no_publication:true});
 const controller=new AbortController(),reason=new Error('Owned Linux UI caller cancellation');ctx.signal=controller.signal;cancellationMarker='/artifacts/cancel-initial-ready';const pending=ctx.call('capture_native_ui_scenario',{...selected,screenshot:false,steps:[{kind:'wait',milliseconds:30000}]}).then(value=>({value}),error=>({error}));const cancelledHelperPid=Number(await wait(()=>readFile(cancellationMarker,'utf8'),'Actual initial snapshot did not complete'));controller.abort(reason);const canceled=await pending;assert.equal(canceled.error.name,'AbortError');assert.equal(canceled.error.cause,reason);assert.equal(ctx.ledger.size,ledger);await assert.rejects(stat('/proc/'+cancelledHelperPid),e=>e.code==='ENOENT');await stat('/proc/'+selected.pid);ctx.signal=undefined;cancellationMarker=null;observations.push({case:'caller-cancellation-after-actual-snapshot',success:true,helper_pid:cancelledHelperPid,helper_absent:true,selected_target_preserved:true,no_publication:true});
 await writeFile('/artifacts/create-ambiguous','owned');await wait(()=>stat('/artifacts/ambiguous.json'),'Second actual GTK window did not become ready');await pause(100);await assert.rejects(ctx.call('observe_native_ui',{...selected,screenshot:false}),/could not be matched/);assert.equal(ctx.ledger.size,ledger);observations.push({case:'ambiguous-accessible-mapping',success:true,no_publication:true});
 await writeFile('/artifacts/PROOF.json',JSON.stringify({success:true,observations,helper_pids:helperPids,all_helpers_physically_absent:true,target_execution:'only-authored-GTK-fixture',platform:process.platform,node:process.version},null,2));
}finally{
 for(const child of children.reverse()){if(!child.result)child.kill('SIGTERM');await Promise.race([child.closed,pause(5000)]);if(!child.result){child.kill('SIGKILL');await child.closed;}await assert.rejects(stat('/proc/'+child.pid),e=>e.code==='ENOENT');}
 await writeFile('/artifacts/CLEANUP.json',JSON.stringify({complete:true,children:children.map(c=>({pid:c.pid,...c.result,physically_absent:true}))},null,2));
}
